  "case_id": "edge-high-frequency-operations",
  "baseline_observation": "The existing brief and hierarchy criteria do not explicitly reject one universal page pattern when novice comprehension and expert high-frequency comparison or batch work require different structure.",
  "candidate_observation": "The candidate makes task frequency, experience, switching, comparison, batch behavior, reachable failure and recovery states, and consequential disclosure explicit decision inputs.",
  "evidence_refs": [
    "source:govuk-role-context",
    "evaluation:edge-high-frequency-operations"
  ]
}

{
  "schema_version": "maestro_expertise_case_artifact_v1",
  "case_id": "non-trigger-backend-orchestration",
  "baseline_observation": "Backend queue retry and idempotency are outside the product-design domain even though they use flow and state vocabulary.",
  "candidate_observation": "The candidate's triggers and not-for boundary keep backend orchestration outside the Pack and return no local Guides.",
  "evidence_refs": [
    "evaluation:non-trigger-backend-orchestration"
  ]
}

{
  "schema_version": "maestro_expertise_case_artifact_v1",
  "case_id": "normal-decision-support-page",
  "baseline_observation": "The existing Pack can prioritize visible content but does not require shared versus role-dependent evidence, an end-to-end decision sequence, or correction continuity before CTA placement.",
  "candidate_observation": "The candidate requires role and situation differences, decision evidence, page scope, primary and secondary actions, continuity, and correction paths before visual emphasis.",
  "evidence_refs": [
    "research:.maestro/state/work/web-design-expertise/research-bundle.json",
    "evaluation:normal-decision-support-page"
  ]
}

{
  "schema_version": "maestro_expertise_case_artifact_v1",
  "case_id": "normal-role-aware-onboarding",
  "baseline_observation": "The current route selected design-brief, visual-hierarchy-layout, and interaction-responsive-accessibility but no Guide required journey entry and exit conditions or a role-situation-state action map.",
  "candidate_observation": "The candidate adds the information-architecture Guide to the three inherited Guides and requires role, situation, state, evidence, action, entry, exit, recovery, and placement traceability before composition.",
  "evidence_refs": [
    "baseline:.maestro/state/work/web-design-expertise/baseline.json",
    "evaluation:normal-role-aware-onboarding"
  ]
}

{
  "schema_version": "maestro_expertise_case_artifact_v1",
  "case_id": "overlap-scroll-storytelling",
  "baseline_observation": "The existing interactive-web-motion Pack owns explicit scroll-driven animation, pin, scrub, parallax, reduced motion, and runtime performance decisions.",
  "candidate_observation": "The candidate retains that boundary: it may state a justified interaction job, but the motion-specific request selects interactive-web-motion rather than the web-structure extension.",
  "evidence_refs": [
    "repo:src/maestro/resources/registry/expertise-packs/interactive-web-motion.json",
    "evaluation:overlap-scroll-storytelling"
  ]
}

